  8	    public BTreeNode(int minimumDegree, boolean leaf) {
  9	        this.keys = new int[2 * minimumDegree - 1];
 10	        this.minimumDegree = minimumDegree;
 11	        this.children = new BTreeNode[2 * minimumDegree];
 12	        this.keyCount = 0;
 13	        this.leaf = leaf;
 14	    }
 15	
 16	    void initializeWithSingleKey(int key) {
 17	        keys[0] = key;
 18	        keyCount = 1;
 19	    }
 20	
 21	    void setChild(int index, BTreeNode child) {
 22	        children[index] = child;
 23	    }
 24	
 25	    boolean isFull() {
 26	        return keyCount == maxKeys();
 27	    }
 28	
 29	    private int maxKeys() {
 30	        return 2 * minimumDegree - 1;
 31	    }
 32	
 33	    private int insertionPosition(int key) {
 34	        int index = keyCount - 1;
 35	        while (index >= 0 && keys[index] > key) {
 36	            index--;
 37	        }
 38	        return index + 1;
 39	    }
 40	
 41	    void insertNonFull(int key) {
 42	        if (leaf) {
 43	            insertIntoLeaf(key);
 44	            return;
 45	        }
 46	
 47	        insertIntoChild(key);
 48	    }
 49	
 50	    private void insertIntoLeaf(int key) {
 51	        insertKeyAt(insertionPosition(key), key);
 52	    }
 53	
 54	    private void insertIntoChild(int key) {
 55	        int childIndex = insertionPosition(key);
 56	        childIndex = prepareChildForInsert(childIndex, key);
 57	        children[childIndex].insertNonFull(key);
 58	    }
 59	
 60	    private int prepareChildForInsert(int childIndex, int key) {
 61	        if (!children[childIndex].isFull()) {
 62	            return childIndex;
 63	        }
 64	
 65	        splitChild(childIndex, children[childIndex]);
 66	        return keys[childIndex] < key ? childIndex + 1 : childIndex;
 67	    }
 68	
 69	    void splitChild(int childIndex, BTreeNode child) {
 70	        BTreeNode rightSibling = createRightSibling(child);
 71	        int medianKey = medianKey(child);
 72	        trimToLeftHalf(child);
 73	        insertChildAt(childIndex + 1, rightSibling);
 74	        insertKeyAt(childIndex, medianKey);
 75	    }
 76	
 77	    private BTreeNode createRightSibling(BTreeNode node) {
 78	        BTreeNode sibling = new BTreeNode(node.minimumDegree, node.leaf);
 79	        sibling.keyCount = node.minimumDegree - 1;
 80	        System.arraycopy(node.keys, node.minimumDegree, sibling.keys, 0, node.minimumDegree - 1);
 81	        if (!node.leaf) {
 82	            System.arraycopy(node.children, node.minimumDegree, sibling.children, 0, node.minimumDegree);
 83	        }
 84	        return sibling;
 85	    }
 86	
 87	    private int medianKey(BTreeNode node) {
 88	        return node.keys[node.minimumDegree - 1];
 89	    }
 90	
 91	    private void trimToLeftHalf(BTreeNode node) {
 92	        node.keyCount = node.minimumDegree - 1;
 93	    }
 94	
 95	    private void insertChildAt(int index, BTreeNode child) {
 96	        shiftChildrenRight(index);
 97	        children[index] = child;
 98	    }
 99	
100	    private void insertKeyAt(int index, int key) {
101	        shiftKeysRight(index);
102	        keys[index] = key;
103	        keyCount++;
104	    }
105	
106	    private void shiftKeysRight(int fromIndex) {
107	        System.arraycopy(keys, fromIndex, keys, fromIndex + 1, keyCount - fromIndex);
108	    }
109	
110	    private void shiftChildrenRight(int fromIndex) {
111	        System.arraycopy(children, fromIndex, children, fromIndex + 1, keyCount - fromIndex + 1);
112	    }
