157	class BTree {
158	    private BTreeNode root;
159	    private final int minimumDegree;
160	
161	    public BTree(int minimumDegree) {
162	        this.root = null;
163	        this.minimumDegree = minimumDegree;
164	    }
165	
166	    String traversal() {
167	        StringBuilder traversal = new StringBuilder();
168	        if (!isEmpty()) {
169	            root.appendTraversal(traversal);
170	        }
171	        return traversal.toString();
172	    }
173	
174	    void traverse() {
175	        System.out.print(traversal());
176	    }
177	
178	    BTreeNode search(int key) {
179	        return isEmpty() ? null : root.search(key);
180	    }
181	
182	    boolean contains(int key) {
183	        return search(key) != null;
184	    }
185	
186	    void insert(int key) {
187	        if (isEmpty()) {
188	            createRoot(key);
189	            return;
190	        }
191	
192	        if (root.isFull()) {
193	            splitRootAndInsert(key);
194	            return;
195	        }
196	
197	        root.insertNonFull(key);
198	    }
199	
200	    private boolean isEmpty() {
201	        return root == null;
202	    }
203	
204	    private void createRoot(int key) {
205	        root = new BTreeNode(minimumDegree, true);
206	        root.initializeWithSingleKey(key);
207	    }
208	
209	    private void splitRootAndInsert(int key) {
210	        BTreeNode newRoot = new BTreeNode(minimumDegree, false);
211	        newRoot.setChild(0, root);
212	        newRoot.splitChild(0, root);
213	        newRoot.insertAfterRootSplit(key);
214	        root = newRoot;
215	    }
216	}
